  "evt.travel.cheer.early": "Reservar cedo é a melhor poupança da viagem: os bilhetes não esperam que a tua poupança esteja pronta.",
  "evt.travel.cheer.onTrack": "O orçamento da viagem enche ao ritmo certo — as férias sabem muito melhor quando já estão pagas.",
