  "evt.funeral.ms.aid": "Verificar os apoios: subsídio por morte, conta do falecido, seguros e fundos",
  "evt.funeral.ms.ceremony": "Cerimónia",
  "evt.funeral.cheer.early": "Prever é proteger os teus: um orçamento feito a frio evita decisões caras tomadas à pressa e em luto.",
  "evt.funeral.cheer.onTrack": "O orçamento detalhado é o teu melhor aliado: as agências funerárias têm de o dar gratuitamente — pede vários, as diferenças são enormes.",
  "evt.funeral.cheer.behind": "Não te deixes pressionar: só alguns serviços são obrigatórios por lei, tudo o resto é negociável. E existem apoios (subsídio por morte, levantamento da conta do falecido).",
  "evt.funeral.cheer.lastStretch": "Força. Foca-te no essencial, deixa que te ajudem com a papelada e verifica cada linha do orçamento final antes de assinar.",
