  "evt.party.style.enfant.label": "🎈 Infantil",
  "evt.party.style.enfant.tip": "O gasto habitual em casa ronda os 200 € no total. O animador profissional (200-300 €) é a rubrica decisiva: aos cinco anos, jogos organizados por dois pais fazem o mesmo efeito.",
  "evt.party.style.adulte.label": "🥂 Adultos",
  "evt.party.style.adulte.tip": "Um cocktail em pé custa metade de um jantar sentado e faz circular as pessoas. Pede a cada um que traga uma garrafa — clássico e eficaz.",
  "evt.party.style.surprise.label": "🎁 Surpresa",
  "evt.party.style.surprise.tip": "Orçamento secreto significa pagamentos discretos e repartidos. Cria o evento no teu espaço pessoal (não no partilhado!) para que a surpresa continue surpresa.",
