  "notifPrefs.cat.seasonal.label": "Prazos da época",
  "notifPrefs.cat.seasonal.desc": "Janelas curtas: declaração de IRS, regresso às aulas, fim de ano.",
  "notifPrefs.cat.comeback.label": "Retomar o contacto",
  "notifPrefs.cat.comeback.desc": "Depois de uma longa ausência, e só se houver algo novo para te mostrar.",
